func (this *StyledText) GetSelectionText() string {
	this.CheckWidget()
	if this.blockSelection && this.blockXLocation != -1 {
		return this.GetBlockSelectionText(this.content.GetLineDelimiter())
	}
	return jrt.ArraysAsList(this.selection).Map(func(sel *Point) string {
		return this.content.GetTextRange(sel.X, sel.Y-sel.X)
	}).Collect(jrt.CollectorsJoining("")).(string)
}

func (this *StyledText) GetStyleRangeAtOffset(offset int32) *StyleRange {
	this.CheckWidget()
	if offset < 0 || offset >= this.GetCharCount() {
		Error(ERROR_INVALID_ARGUMENT)
	}
	if !this.IsListening(STLineGetStyle) {
		var ranges []*StyleRange = this.renderer.GetStyleRanges(offset, 1, true)
		if ranges != (nil) {
			return ranges[0]
		}
	}
	return nil
}

func (this *StyledText) GetStyleRanges() []*StyleRange {
	this.CheckWidget()
	return this.GetStyleRangesStartLengthIncludeRanges(0, this.content.GetCharCount(), true)
}

func (this *StyledText) GetStyleRangesIncludeRanges(includeRanges bool) []*StyleRange {
	this.CheckWidget()
	return this.GetStyleRangesStartLengthIncludeRanges(0, this.content.GetCharCount(), includeRanges)
}

func (this *StyledText) GetStyleRangesStartLength(start int32, length int32) []*StyleRange {
	this.CheckWidget()
	return this.GetStyleRangesStartLengthIncludeRanges(start, length, true)
}

func (this *StyledText) GetStyleRangesStartLengthIncludeRanges(start int32, length int32, includeRanges bool) []*StyleRange {
	this.CheckWidget()
	var contentLength int32 = this.GetCharCount()
	var end int32 = start + length
	if start > end || start < 0 || end > contentLength {
		Error(ERROR_INVALID_RANGE)
	}
	if !this.IsListening(STLineGetStyle) {
		var ranges []*StyleRange = this.renderer.GetStyleRanges(start, length, includeRanges)
		if ranges != (nil) {
			return ranges
		}
	}
	return make([]*StyleRange, 0)
}

func (this *StyledText) GetTabStops() []int32 {
	this.CheckWidget()
	if this.tabs == (nil) {
		return []int32{this.renderer.tabWidth}
	}
	var result []int32 = make([]int32, int32(len(this.tabs)))
	copy(result[0:], this.tabs[0:0+int32(len(this.tabs))])
	return result
}

func (this *StyledText) GetTabs() int32 {
	this.CheckWidget()
	return this.tabLength
}
